// PDF / PNG export for any DataTableView table.
//
// buildTableExport() is pure (no Flutter, no Firestore): it turns the
// table's columns + its rows — every filtered row across ALL pages, in the
// on-screen sort, as given by DataTableController.sortedRows — into plain
// text plus the report header (title, generated time, generated by,
// active filters, date range). The two renderers only lay that out:
//   * PDF  — package:pdf, A4 (landscape when the table is wide), header on
//            page 1, "Page X of Y" footer on every page, header row
//            repeated on every page.
//   * PNG  — package:image (already a dependency), one tall image with the
//            same header block and a "Page 1 of 1" footer.
// Delivery: PDF via package:printing (Android share/save sheet, browser
// download on web); PNG via file_picker's saveFile (Android "Save as",
// browser download on web).
import 'dart:typed_data';

import 'package:file_picker/file_picker.dart';
import 'package:image/image.dart' as img;
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

import 'data_table_view.dart';

class TableExport {
  final String title;
  final DateTime generatedAt;
  final String generatedBy;
  // Human-readable active filters, e.g. 'Status: OVERDUE', 'Search: "WP"'.
  final List<String> filters;
  final String? sortDescription;
  // 'YYYY-MM-DD to YYYY-MM-DD' covered by the exported rows' date column.
  final String? dateRange;
  final List<String> headers;
  final List<List<String>> rows;

  const TableExport({
    required this.title,
    required this.generatedAt,
    required this.generatedBy,
    required this.filters,
    required this.headers,
    required this.rows,
    this.sortDescription,
    this.dateRange,
  });

  // More than 5 columns doesn't fit portrait A4 legibly.
  bool get landscape => headers.length > 5;

  List<String> get headerLines => [
    title,
    'Generated: ${formatExportTimestamp(generatedAt)}',
    'Generated by: $generatedBy',
    'Filters: ${filters.isEmpty ? 'none (all rows)' : filters.join(' | ')}',
    if (sortDescription != null) 'Sorted by: $sortDescription',
    'Date range: ${dateRange ?? '-'}',
    'Rows: ${rows.length}',
  ];

  String fileName(String extension) {
    final safe = title.replaceAll(RegExp(r'[^A-Za-z0-9]+'), '_').replaceAll(RegExp(r'_+$'), '');
    final stamp = formatExportTimestamp(generatedAt).replaceAll(RegExp(r'[^0-9]'), '');
    return '${safe}_$stamp.$extension';
  }
}

String _two(int n) => n.toString().padLeft(2, '0');

// "YYYY-MM-DD HH:mm"
String formatExportTimestamp(DateTime d) =>
    '${d.year}-${_two(d.month)}-${_two(d.day)} ${_two(d.hour)}:${_two(d.minute)}';

// "YYYY-MM-DD" — the one date format every Service/Repair table uses.
String formatTableDate(DateTime? d) =>
    d == null ? '-' : '${d.year}-${_two(d.month)}-${_two(d.day)}';

final RegExp _ymd = RegExp(r'\d{4}-\d{2}-\d{2}');

TableExport buildTableExport<T>({
  required String title,
  required List<DataTableColumn<T>> columns,
  required List<T> rows,
  required String generatedBy,
  List<String> filters = const [],
  String? sortDescription,
  DateTime? now,
}) {
  final cols = columns.where((c) => c.exportValue != null).toList();
  final data = [
    for (final r in rows) [for (final c in cols) c.exportValue!(r)],
  ];
  String? range;
  final dateIdx = cols.indexWhere((c) => c.isDate);
  if (dateIdx >= 0) {
    final dates = [
      for (final row in data)
        if (_ymd.firstMatch(row[dateIdx]) != null) _ymd.firstMatch(row[dateIdx])!.group(0)!,
    ]..sort();
    if (dates.isNotEmpty) range = '${dates.first} to ${dates.last}';
  }
  return TableExport(
    title: title,
    generatedAt: now ?? DateTime.now(),
    generatedBy: generatedBy,
    filters: filters,
    sortDescription: sortDescription,
    dateRange: range,
    headers: [for (final c in cols) c.label],
    rows: data,
  );
}

// ---------------- PDF ----------------

// The built-in Helvetica only covers Latin-1; map the few typographic
// characters the tables use and replace anything else rather than letting
// the PDF render garbage. (A Unicode font is used instead when one could be
// loaded — see exportTablePdf.)
String latin1Safe(String s) {
  final b = StringBuffer();
  for (final r in s.replaceAll('—', '-').replaceAll('–', '-').replaceAll('…', '...').runes) {
    b.write((r < 32 && r != 10) || (r > 126 && r < 160) || r > 255 ? '?' : String.fromCharCode(r));
  }
  return b.toString();
}

Future<Uint8List> renderTableExportPdf(TableExport e, {pw.Font? font, pw.Font? boldFont}) async {
  final unicode = font != null;
  String t(String s) => unicode ? s : latin1Safe(s);
  final doc = pw.Document(
    title: e.title,
    theme: unicode ? pw.ThemeData.withFont(base: font, bold: boldFont ?? font) : null,
  );
  final format = e.landscape ? PdfPageFormat.a4.landscape : PdfPageFormat.a4;
  final lines = e.headerLines;
  doc.addPage(
    pw.MultiPage(
      pageFormat: format,
      margin: const pw.EdgeInsets.all(24),
      header: (ctx) => ctx.pageNumber == 1
          ? pw.Padding(
              padding: const pw.EdgeInsets.only(bottom: 10),
              child: pw.Column(
                crossAxisAlignment: pw.CrossAxisAlignment.start,
                children: [
                  pw.Text(
                    t(lines.first),
                    style: pw.TextStyle(fontSize: 15, fontWeight: pw.FontWeight.bold),
                  ),
                  pw.SizedBox(height: 4),
                  for (final l in lines.skip(1))
                    pw.Text(t(l), style: const pw.TextStyle(fontSize: 8.5)),
                ],
              ),
            )
          : pw.Padding(
              padding: const pw.EdgeInsets.only(bottom: 6),
              child: pw.Text(
                t('${e.title} (continued)'),
                style: const pw.TextStyle(fontSize: 8.5, color: PdfColors.grey700),
              ),
            ),
      footer: (ctx) => pw.Container(
        alignment: pw.Alignment.centerRight,
        margin: const pw.EdgeInsets.only(top: 6),
        child: pw.Text(
          t(
            'Page ${ctx.pageNumber} of ${ctx.pagesCount}  -  ${formatExportTimestamp(e.generatedAt)}',
          ),
          style: const pw.TextStyle(fontSize: 8, color: PdfColors.grey700),
        ),
      ),
      build: (ctx) => [
        if (e.rows.isEmpty)
          pw.Text('No rows match the current filter.')
        else
          pw.TableHelper.fromTextArray(
            headers: [for (final h in e.headers) t(h.toUpperCase())],
            data: [
              for (final r in e.rows) [for (final c in r) t(c)],
            ],
            headerCount: 1,
            headerStyle: pw.TextStyle(fontSize: 7.5, fontWeight: pw.FontWeight.bold),
            headerDecoration: const pw.BoxDecoration(color: PdfColors.blue50),
            cellStyle: const pw.TextStyle(fontSize: 7.5),
            cellAlignment: pw.Alignment.centerLeft,
            cellPadding: const pw.EdgeInsets.symmetric(horizontal: 3, vertical: 2.5),
            oddRowDecoration: const pw.BoxDecoration(color: PdfColors.grey100),
            border: pw.TableBorder.all(color: PdfColors.grey400, width: 0.4),
          ),
      ],
    ),
  );
  return doc.save();
}

// ---------------- PNG ----------------

String asciiSafe(String s) {
  final b = StringBuffer();
  for (final r in latin1Safe(s).runes) {
    b.write(r > 126 ? '?' : String.fromCharCode(r));
  }
  return b.toString();
}

int _textWidth(img.BitmapFont f, String s) {
  var w = 0;
  for (final c in s.codeUnits) {
    w += f.characters[c]?.xAdvance ?? 0;
  }
  return w;
}

String _fit(img.BitmapFont f, String s, int maxWidth) {
  if (_textWidth(f, s) <= maxWidth) return s;
  var out = s;
  while (out.isNotEmpty && _textWidth(f, '$out..') > maxWidth) {
    out = out.substring(0, out.length - 1);
  }
  return '$out..';
}

Uint8List renderTableExportPng(TableExport e) {
  final font = img.arial14;
  final titleFont = img.arial24;
  const pad = 16, rowH = 22, cellPad = 6, maxColW = 280, minColW = 50;
  final headers = [for (final h in e.headers) asciiSafe(h.toUpperCase())];
  final rows = [
    for (final r in e.rows) [for (final c in r) asciiSafe(c)],
  ];
  final colW = <int>[
    for (var i = 0; i < headers.length; i++)
      ([
                _textWidth(font, headers[i]),
                for (final r in rows) _textWidth(font, r[i]),
              ].reduce((a, b) => a > b ? a : b) +
              cellPad * 2)
          .clamp(minColW, maxColW),
  ];
  final lines = [for (final l in e.headerLines) asciiSafe(l)];
  final tableW = colW.isEmpty ? 0 : colW.reduce((a, b) => a + b);
  final headerW = [
    _textWidth(titleFont, lines.first),
    for (final l in lines.skip(1)) _textWidth(font, l),
  ].reduce((a, b) => a > b ? a : b);
  final width = (tableW > headerW ? tableW : headerW) + pad * 2;
  final headerBlockH = 34 + (lines.length - 1) * 18 + 10;
  final bodyRows = rows.isEmpty ? 1 : rows.length;
  final height = pad + headerBlockH + rowH * (bodyRows + 1) + 36;

  final image = img.Image(width: width, height: height);
  img.fill(image, color: img.ColorRgb8(255, 255, 255));
  final black = img.ColorRgb8(15, 23, 42);
  final grey = img.ColorRgb8(100, 116, 139);
  final line = img.ColorRgb8(203, 213, 225);

  var y = pad;
  img.drawString(image, lines.first, font: titleFont, x: pad, y: y, color: black);
  y += 34;
  for (final l in lines.skip(1)) {
    img.drawString(image, l, font: font, x: pad, y: y, color: grey);
    y += 18;
  }
  y += 10;

  void drawRow(List<String> cells, int top, img.Color? bg, {bool bold = false}) {
    if (bg != null) {
      img.fillRect(image, x1: pad, y1: top, x2: pad + tableW - 1, y2: top + rowH - 1, color: bg);
    }
    var x = pad;
    for (var i = 0; i < cells.length; i++) {
      final text = _fit(font, cells[i], colW[i] - cellPad * 2);
      img.drawString(image, text, font: font, x: x + cellPad, y: top + 4, color: black);
      if (bold) {
        img.drawString(image, text, font: font, x: x + cellPad + 1, y: top + 4, color: black);
      }
      x += colW[i];
    }
    img.drawLine(
      image,
      x1: pad,
      y1: top + rowH - 1,
      x2: pad + tableW - 1,
      y2: top + rowH - 1,
      color: line,
    );
  }

  if (headers.isNotEmpty) {
    drawRow(headers, y, img.ColorRgb8(234, 241, 255), bold: true);
    y += rowH;
    if (rows.isEmpty) {
      img.drawString(
        image,
        'No rows match the current filter.',
        font: font,
        x: pad + cellPad,
        y: y + 4,
        color: grey,
      );
      y += rowH;
    }
    for (var i = 0; i < rows.length; i++) {
      drawRow(rows[i], y, i.isOdd ? img.ColorRgb8(244, 246, 250) : null);
      y += rowH;
    }
    // Column separators over the whole table.
    var x = pad;
    final tableTop = y - rowH * (bodyRows + 1);
    for (var i = 0; i <= colW.length; i++) {
      img.drawLine(image, x1: x, y1: tableTop, x2: x, y2: y - 1, color: line);
      if (i < colW.length) x += colW[i];
    }
  }
  final footer = 'Page 1 of 1  -  ${formatExportTimestamp(e.generatedAt)}';
  img.drawString(
    image,
    footer,
    font: font,
    x: width - pad - _textWidth(font, footer),
    y: height - 26,
    color: grey,
  );
  return img.encodePng(image);
}

// ---------------- delivery ----------------

// Tries a Unicode font for the PDF (names in Sinhala/Tamil etc. would
// otherwise come out as '?'); falls back to built-in Helvetica + latin1Safe
// when it can't be fetched (offline, slow network).
Future<void> exportTablePdf(TableExport e) async {
  pw.Font? font;
  pw.Font? bold;
  try {
    font = await PdfGoogleFonts.notoSansRegular().timeout(const Duration(seconds: 6));
    bold = await PdfGoogleFonts.notoSansBold().timeout(const Duration(seconds: 6));
  } catch (_) {
    font = null;
    bold = null;
  }
  final bytes = await renderTableExportPdf(e, font: font, boldFont: bold);
  await Printing.sharePdf(bytes: bytes, filename: e.fileName('pdf'));
}

Future<void> exportTablePng(TableExport e) async {
  final bytes = renderTableExportPng(e);
  await FilePicker.saveFile(
    fileName: e.fileName('png'),
    bytes: bytes,
    mimeType: 'image/png',
    dialogTitle: 'Save ${e.title}',
  );
}
